/* ############################### PAGINES ############################### */
function showPage() {
	removeEvents();
	$(".cntPage").show();
	if ( pagina == 1 ) page1();
	else if ( pagina == 2 ) page2();
	else if ( pagina == 3 ) page3();
	else if ( pagina == 4 ) page4();
	else if ( pagina == 5 ) page5();
	else if ( pagina == 6 ) page6();
	else if ( pagina == 7 ) page7();
	else if ( pagina == 8 ) page8();
	else if ( pagina == 9 ) page9();
	else if ( pagina == 10 ) enviaDades();
}

function page1() {
	var request = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/mostrar_pagina_descompte_amic.php",
		method: "GET",
		data: {
			dispositiu: dispositiu
		},
		dataType: "html"
	});

	request.done(function(page) {
		$("#contingut").html(page);

		$('#cntPage').on('click', '.inscripcio', function() {
			showModalLoading();
			pagina++;
			showPage();
		});
	});

	request.fail(function(jqXHR, textStatus, errorThrown) {
		errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request Page 1: ");
	});
}

