//Es mostra la info per escollir l'edició del curs del primer persona
function page3() {
	var request = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/mostrar_pagina_3_descompte_amic.php",
		method: "GET",
		data: {
			course: dadesPersona1[0],
			dispositiu: dispositiu
		},
		dataType: "html"
	});

	request.done(function(page) {
		$("#cntPage").html(page);
		if ( dadesPersona1[1] != 0 && dadesPersona1[2] != '' )
		 	$( "#dates-" + dadesPersona1[1] + "-" + dadesPersona1[2] ).add('marcat');

		hideModalLoading();

		$('#cntPage').on('click', '.datesEdicio', function() {
			$('.datesEdicio').removeClass('marcat');
			$(this).addClass('marcat');
		});

		$('#cntPage').on('click', '.continua', function() {
			if ( !$('.datesEdicio.marcat')[0] ) {
				mostrarModalError( "Has de marcar una edició!");
			}
			else {
				dadesPersona1[1] = $('.datesEdicio.marcat').attr('id').split('-')[1];
				dadesPersona1[2] = $('.datesEdicio.marcat').attr('id').split('-')[2];
				pagina++;
				showModalLoading();
				showPage();
			}
		});
		$('#cntPage').on('click', '.enrere', function() {
			pagina--;
			showModalLoading();
			showPage();
		});
	});

	request.fail(function(jqXHR, textStatus, errorThrown) {
		errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request mostrar cursos per hores: ");
	});
}

