//S'envia inscripcions, s'envia missatge normal a persona X i missatge més pagament a persona Y
function enviaDades() {
	var request = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/enviar_inscripcio_descompte_amic.php",
		method: "GET",
		data: {
			dniPagador: dniPagador,
			perfil1: dadesPersona1[11],
			perfil2: dadesPersona2[11],
			titulacio1: dadesPersona1[12],
			titulacio2: dadesPersona2[12],
			comentaris1: dadesPersona1[13],
			comentaris2: dadesPersona2[13],
			conegut1: dadesPersona1[14],
			conegut2: dadesPersona2[14]
		},
		dataType: "html"
	});

	request.done(function(page) {
		if (!page.toLowerCase().includes("error")) {
			var urlConf = "https://www.prisma.cat/descompte-amic/confirmacio/";
			urlConf +=  page;
			hideModalLoading();
			//redireccioUrl a /confirmacio/url-amigable/idInsc on la idIsc està codificada amb hash
			window.location.replace(urlConf);
		} else {
			hideModalLoading();
			mostrarModalError(page);
			//enviar un missatge a suport
		}
	});

	request.fail(function(jqXHR, textStatus, errorThrown) {
		errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request mostrar cursos per hores: ");
	});
}

